import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    n = int(input_data[0])
    k = int(input_data[1])

    max_pairs = n * (n - 1) // 2
    if max_pairs <= k:
        print("no solution")
        return

    points = []
    for i in range(n):
        points.append((i, 0))

    for x, y in points:
        print(f"{x} {y}")

if __name__ == "__main__":
    main()
